const reduced=matchMedia('(prefers-reduced-motion: reduce)');const dialog=document.querySelector('dialog');let data;const contentReady=fetch('assets/content.json').then(r=>r.json()).then(d=>data=d);document.querySelectorAll('[data-detail]').forEach(b=>b.addEventListener('click',async()=>{await contentReady;const p=data.projects[+b.dataset.detail];const box=dialog.querySelector('.dialog-content');box.replaceChildren();const h=document.createElement('h2');h.textContent=p.short;const text=document.createElement('pre');text.textContent=p.body;box.append(h,text);dialog.showModal()}));dialog.querySelector('.close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',x===b));document.querySelectorAll('.project').forEach((p,i)=>p.hidden=b.dataset.filter==='apps'?i>=5:b.dataset.filter==='agents'?i<5:false)});document.querySelectorAll('.media video').forEach(v=>v.addEventListener('play',()=>document.querySelectorAll('.media video').forEach(x=>{if(x!==v)x.pause()})));const hero=document.querySelector('.hero');hero.addEventListener('pointermove',e=>{if(reduced.matches||e.pointerType==='touch')return;hero.style.setProperty('--mx',`${(e.clientX/innerWidth-.5)*22}px`);hero.style.setProperty('--my',`${(e.clientY/innerHeight-.5)*18}px`)});hero.addEventListener('pointerleave',()=>{hero.style.setProperty('--mx','0px');hero.style.setProperty('--my','0px')});window.addEventListener('scroll',()=>document.documentElement.style.setProperty('--progress',`${scrollY/(document.documentElement.scrollHeight-innerHeight)*100}%`),{passive:true});